; ***************************************************************; * Filename: BACKUP/ASM					*; * Revision: 06.03.01						*; * Rev Date: 03 Dec 97						*; ***************************************************************; * DOS file and disk backup utility				*; *								*; ***************************************************************;*GET	BACKUP1;;	Save PC for later use;CORE$	DEFL	$<-8+1<+8	; Set to next page;MIRBU	EQU	CORE$	IF	@ZMAC	ORG	MIRBU		; Load origin	PHASE	BACKUP		; Set for MIRROR exec	ELSE	ORG	BACKUP		; Set for MIRROR exec	LORG	MIRBU		; Load origin	ENDIF;	SUBTTL	'<Mirror Image Backup>';*GET	BACKUP2;MIRSIZ	EQU	$<-8+1<+8-BACKUP;;	Adjust PC and load address for CLASS backup;CLSBU	EQU	CORE$+MIRSIZ	IF	@ZMAC	DEPHASE	ORG	CLSBU	PHASE	BACKUP	ELSE	ORG	BACKUP	LORG	CLSBU	ENDIF;	SUBTTL	'<Backup By Class>';*GET	BACKUP3;LAST	EQU	$;	END	BACKUP